#include "so101_gazebo_demo/pick_place/transition_contract.hpp"
namespace so101_gazebo_demo::pick_place { void TransitionContractRegistry::registerContract(TransitionKey k,std::shared_ptr<const ITransitionContract> c){contracts_[k]=std::move(c);} bool TransitionContractRegistry::hasContract(TransitionKey k)const noexcept{auto i=contracts_.find(k);return i!=contracts_.end()&&i->second;} ValidationResult TransitionContractRegistry::validatePrecondition(TransitionKey k,const WorldSnapshot&w)const{auto i=contracts_.find(k);return i==contracts_.end()?ValidationResult{false,{{FailureCategory::CONFIGURATION,"MISSING_TRANSITION_CONTRACT","contract missing",{}}},{}}:i->second->validatePrecondition(w);} ValidationResult TransitionContractRegistry::validate(TransitionKey k,const WorldSnapshot&a,const WorldSnapshot&b,const ActionResult&r)const{auto i=contracts_.find(k);return i==contracts_.end()?ValidationResult{false,{{FailureCategory::CONFIGURATION,"MISSING_TRANSITION_CONTRACT","contract missing",{}}},{}}:i->second->validate(a,b,r);} ValidationResult TransitionContractRegistry::validateResume(TransitionKey k,const WorldSnapshot&a,const WorldSnapshot&b)const{return validate(k,a,b,{ActionStatus::SUCCEEDED,{}});} ValidationResult AlwaysPassValidator::validatePrecondition(const WorldSnapshot&)const{return {true,{},{}};} ValidationResult AlwaysPassValidator::validate(const WorldSnapshot&,const WorldSnapshot&,const ActionResult&)const{return {true,{},{}};} }
